#[path="../../research/sources/backend/tip_compile_module.rs"] mod original;
#[path="../src/member_calls.rs"] mod port;
fn main(){let t=original::Vm::new().unwrap();let mut count=0;for kind in 0..10u32{for class in 0..3u32{for flag in [0u32,0x2000]{let mut v=t.clone();v.memory.map(0x70000000,vec![0;0x10000]).unwrap();v.set_register("ESP",0x70008000).unwrap();let got=v.invoke(0x0fac3506,&[kind,class,flag],&mut original::NoHost,100).unwrap() as u16;assert_eq!(got,port::select_member_base(&port::BASE_OPCODE_SNAPSHOT,kind,class,flag!=0));count+=1;}}}for base in [0x300,0x310,0x320,0x330,0x340,0x350,0x123]{for (addr,flags) in [(0x0fac38ae,0x8000),(0x0fb91384,0x0800)]{let mut v=t.clone();v.memory.map(0x70000000,vec![0;0x10000]).unwrap();v.set_register("ESP",0x70008000).unwrap();let got=v.invoke(addr,&[base],&mut original::NoHost,100).unwrap() as u16;assert_eq!(got,port::transform_member_opcode(base as u16,flags,3,0,None).unwrap().0);count+=1;}}println!("{count} member opcode/base comparisons pass against original residual VM");}
